"""Built-in AHM member codec, independently implemented from generated byte probes.

Each member starts four little-endian 16-bit XOR lanes. After every four words,
the lane words advance modulo 65536. A final unpaired byte is stored unchanged.
This module supports the AHM format only; it never loads a third-party EXE.
"""
from __future__ import annotations

from pathlib import Path
import re
import struct
import tempfile

import numpy as np

from .formats import exact, header_transform, read_archive, safe_name

BLOCK = 512 * 1024
_first = np.array([0x0F9D, 0xD45B, 0xAFEF, 0x00E1], dtype=np.uint64)
_steps = np.array([0x9E1F, 0xC5E3, 0x0008, 0x713A], dtype=np.uint64)
_key = ((_first + np.arange(65536, dtype=np.uint64)[:, None] * _steps) & 0xFFFF).astype("<u2").view(np.uint8).reshape(-1)
_key.flags.writeable = False
del _first, _steps
_EMA_EXTENSION = re.compile(rb"\.(?:bmp|tga|png|jpg|jpeg|dds)", re.IGNORECASE)


def ema_parts(data: bytes):
    """The first eight EMA bytes are opaque metadata, retained when editing."""
    end = data.find(b"\0", 8, 64)
    extension = data[8:end] if end >= 8 else b""
    if len(data) < 10 or not _EMA_EXTENSION.fullmatch(extension):
        raise ValueError("不支持的 EMA 图片封装")
    return data[:end + 1], data[end + 1:], extension.decode("ascii")


def transform(data: bytes, offset=0, *, final=True) -> bytes:
    """Encrypt or decrypt bytes at an even offset from the start of one member."""
    if offset < 0 or offset % 2 or (not final and len(data) % 2):
        raise ValueError("AHM stream chunks must begin on 16-bit boundaries")
    result = bytearray(data)
    view = np.frombuffer(result, dtype=np.uint8)
    length = len(data) // 2 * 2
    cursor = 0
    while cursor < length:
        key_offset = (offset + cursor) % BLOCK
        size = min(length - cursor, BLOCK - key_offset)
        np.bitwise_xor(view[cursor:cursor + size], _key[key_offset:key_offset + size], out=view[cursor:cursor + size])
        cursor += size
    return bytes(result)


def _copy_member(source, target, length, prefix=b""):
    remaining, offset = length, 0
    while remaining:
        size = min(BLOCK, remaining)
        block = prefix + exact(source, size - len(prefix))
        prefix = b""
        target.write(transform(block, offset, final=size == remaining))
        remaining -= size
        offset += size


def pack_directory(directory: Path) -> Path:
    directory = Path(directory).resolve()
    output = directory.parent / (directory.name + ".pp")
    files = sorted(directory.iterdir(), key=lambda p: p.name.casefold())
    if not files or len(files) > 99999:
        raise ValueError("待编码文件夹必须包含 1 到 99999 个文件")
    records, names = [], set()
    offset = len(files) * 268 + 9
    table = bytearray()
    for path in files:
        if not path.is_file() or path.is_symlink():
            raise ValueError("AHM 资源只支持当前文件夹中的普通文件")
        name, prefix = path.name, b""
        extension = path.suffix.lower().encode("ascii", errors="ignore")
        if path.stem.lower().endswith(".ema") and _EMA_EXTENSION.fullmatch(extension):
            name = path.stem
            prefix = bytes(8) + extension + b"\0"
        encoded_name = safe_name(name).encode("cp932")
        if len(encoded_name) >= 260 or name.casefold() in names:
            raise ValueError("资源名称过长或重复：" + name)
        stat = path.stat()
        size = stat.st_size + len(prefix)
        if size > 0xFFFFFFFF or offset + size > 0xFFFFFFFF:
            raise ValueError("AHM 资源包超过 32 位格式大小限制")
        table.extend(encoded_name.ljust(260, b"\0") + struct.pack("<II", size, offset))
        offset += size
        names.add(name.casefold())
        records.append((path, size, prefix, (stat.st_size, stat.st_mtime_ns)))
    created = False
    try:
        with output.open("xb") as target:
            created = True
            target.write(header_transform(b"\x03"))
            target.write(header_transform(struct.pack("<I", len(records))))
            target.write(header_transform(table))
            target.write(header_transform(struct.pack("<I", len(table) + 9)))
            for path, size, prefix, signature in records:
                with path.open("rb") as source:
                    _copy_member(source, target, size, prefix)
                after = path.stat()
                if (after.st_size, after.st_mtime_ns) != signature:
                    raise ValueError("编码期间文件发生变化：" + path.name)
        read_archive(output)
        return output
    except Exception:
        if created:
            output.unlink(missing_ok=True)
        raise


def unpack_archive(archive: Path) -> Path:
    archive = Path(archive).resolve()
    destination = archive.with_suffix("")
    if destination.exists():
        raise ValueError("提取目标已存在，拒绝覆盖：" + str(destination))
    before = archive.stat()
    entries = read_archive(archive)
    if not entries:
        raise ValueError("这不是可提取的 AHM 资源包")
    with tempfile.TemporaryDirectory(prefix=".ahm-", dir=archive.parent) as temporary:
        output = Path(temporary) / "decoded"
        output.mkdir()
        with archive.open("rb") as source:
            for entry in entries:
                source.seek(entry["offset"])
                name, skip = entry["name"], 0
                if name.lower().endswith(".ema"):
                    peek = transform(exact(source, min(entry["size"], 64)), final=entry["size"] <= 64)
                    header, _image, extension = ema_parts(peek)
                    name += extension
                    skip = len(header)
                target = output / safe_name(name)
                source.seek(entry["offset"])
                remaining, position = entry["size"], 0
                with target.open("xb") as stream:
                    while remaining:
                        size = min(BLOCK, remaining)
                        decoded = transform(exact(source, size), position, final=size == remaining)
                        start = max(0, skip - position)
                        stream.write(decoded[start:])
                        position += size
                        remaining -= size
        after = archive.stat()
        if (before.st_size, before.st_mtime_ns) != (after.st_size, after.st_mtime_ns):
            raise ValueError("提取期间资源包发生变化")
        if destination.exists():
            raise ValueError("提取目标被其他程序创建，拒绝覆盖")
        output.replace(destination)
    return destination


def process(path: Path) -> Path:
    path = Path(path)
    return pack_directory(path) if path.is_dir() else unpack_archive(path)
